import Preloader from "../../common/Preloader/Preloader"
import s from "./ProfileInfo.module.css"
import StatusWithHooks from "./Status/StatusWithHooks"

const Profileinfo = (props) => {
  if(!props.profile) { // props.profile == null || typeof props.profile == 'undefined'
    return <Preloader/>
  }
  return (
      <div>
        <div>
        </div>
        <div className={s.description__wrapper}>
          <img className={s.avatar} src={props.profile.photos.small ?? '/static/media/user.a6143582309785dca610.png'} alt="" />
          <div>
            <h3 className={s.fullName}>{props.profile.fullName}</h3>
            <ul className={s.list}>
              <li className={s.item}>About me: {props.profile.aboutMe ?? '-'}</li>
              <StatusWithHooks status={props.status} updateStatus={props.updateStatus}/>
              <li className={s.item}>GitHub: {props.profile.contacts.github ?? '-'}</li>
              <li className={s.item}>Website: {props.profile.contacts.website ?? '-'}</li>
            </ul>
          </div>
        </div>
      </div>
    )
}
export default Profileinfo